function singleDivisorTriplet(nums) {
  const count = new Array(101).fill(0);
  for (const num of nums) {
    count[num]++;
  }
  const values = [...new Set(nums)].sort((x, y) => x - y);
  let total = 0;
  for (let i = 0; i < values.length; i++) {
    for (let j = i; j < values.length; j++) {
      for (let k = j; k < values.length; k++) {
        const a = values[i];
        const b = values[j];
        const c = values[k];
        const sum = a + b + c;
        const divisors = Number(sum % a === 0) + Number(sum % b === 0) + Number(sum % c === 0);
        if (divisors !== 1) {
          continue;
        }
        if (a === b) {
          total += 3 * count[a] * (count[a] - 1) * count[c];
        } else if (b === c) {
          total += 3 * count[a] * count[b] * (count[b] - 1);
        } else {
          total += 6 * count[a] * count[b] * count[c];
        }
      }
    }
  }
  return total;
}

